insert into competencias (nome, tipo, definicao) values
('Comprometimento', 'comportamental', 'Demonstra dedicação e envolvimento com suas atividades, mantendo constância na execução das tarefas e contribuindo para o alcance dos objetivos da equipe e da empresa.'),
